<script setup>
import {ref,computed,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,errorText,clearSession,session} from './api.js';import BusinessPage from '../../components/BusinessPage.vue';
const route=useRoute(),router=useRouter(),kind=route.path==='/reset-password'?'reset':route.path==='/verify-email'?'verify':'request';
const token=ref(new URLSearchParams(route.hash.slice(1)).get('token')||'');if(route.hash)router.replace({path:route.path,query:route.query,hash:''});
const password=ref(''),confirmation=ref(''),busy=ref(false),error=ref(''),message=ref(''),done=ref(false);
const title=computed(()=>kind==='reset'?'Đặt lại mật khẩu':kind==='verify'?'Xác nhận email':'Xác minh email tài khoản');
async function submit(){if(busy.value||done.value)return;error.value='';message.value='';if(kind==='reset'&&(password.value!==confirmation.value||new TextEncoder().encode(password.value).length>72)){error.value='Mật khẩu xác nhận phải khớp, tối đa 72 byte UTF-8.';return}busy.value=true;try{if(kind==='request'){await api('/auth/email-verification/request',{method:'POST'});message.value='Nếu tài khoản đủ điều kiện, yêu cầu đã được tiếp nhận. Vui lòng kiểm tra email.'}else{await api('/auth/'+(kind==='reset'?'password/reset':'email-verification/confirm'),{method:'POST',authenticated:false,body:kind==='reset'?{token:token.value,newPassword:password.value}:{token:token.value}});if(kind==='reset')clearSession();done.value=true;token.value='';password.value=confirmation.value='';message.value=kind==='reset'?'Đã đặt lại mật khẩu. Hãy đăng nhập bằng mật khẩu mới.':'Email đã được xác nhận.'}}catch(e){error.value=e.code==='INVALID_OR_EXPIRED_TOKEN'?'Liên kết không hợp lệ, đã hết hạn hoặc đã được sử dụng. Vui lòng yêu cầu liên kết mới.':errorText(e)}finally{busy.value=false}}
onBeforeUnmount(()=>{token.value='';password.value=confirmation.value=''})
</script><template><BusinessPage :title="title"><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><form v-if="!done" @submit.prevent="submit"><template v-if="kind==='reset'"><label>Mật khẩu mới <input v-model="password" type="password" autocomplete="new-password" minlength="8" required/></label><label>Nhập lại mật khẩu <input v-model="confirmation" type="password" autocomplete="new-password" minlength="8" required/></label></template><p v-if="kind==='request'">{{session.user?.emailVerifiedAt?'Email đã được xác minh.':'Gửi liên kết xác minh đến email tài khoản của bạn.'}}</p><p v-if="kind!=='request'&&!token" role="alert">Thiếu token trong liên kết. Hãy yêu cầu email mới.</p><button :disabled="busy||(kind!=='request'&&!token)">{{busy?'Đang xử lý…':kind==='request'?'Gửi email xác minh':'Xác nhận'}}</button></form><RouterLink to="/login" class="underline">Về đăng nhập / yêu cầu khôi phục</RouterLink></BusinessPage></template>
